/**
 * Seznam věžních a veřejných hodin firmy Ludwig Hainz — stav ke konci roku 1904.
 *
 * Zdroj: „Ortsverzeichnis der bis Ende 1904 zur Aufstellung gebrachten
 * Turm- oder sonstigen öffentlichen Uhren" — firemní leták, tisk Alois
 * Wiesner, Praha. Sken poskytnut z archivu firmy L. Hainz
 * (zdroje/Hainz/hainz-ortsverzeichnis-1904.pdf).
 *
 * Transkripce: OCR (tesseract) + ruční verifikace proti skenu.
 * Identifikace lokalit: německá exonyma → dnešní názvy (wiki seznam exonym
 * + dobové místopisy); geokódování: Nominatim (obec) + OSM Overpass
 * (budova — kostel/radnice/zámek/nádraží, kde jednoznačné do 1,5 km).
 *
 * `presnost: 'budova'` = pin míří na konkrétní stavbu dle OSM;
 * `presnost: 'obec'` = pin na střed obce.
 * `nejiste: true` = identifikace lokality není jednoznačná (viz pozn).
 * `elektro: true` = položka ze závěrečné sekce „Elektrische Uhrenanlagen".
 *
 * VYGENEROVÁNO skriptem — needitovat ručně po jednotlivých záznamech;
 * opravy dělat v identifikační tabulce a přegenerovat.
 */

export type HainzKategorie =
  | 'sakralni'    // kostely, kláštery, synagogy
  | 'radnice'
  | 'zamek'
  | 'skola'
  | 'nadrazi'
  | 'prumysl'     // továrny, cukrovary, pivovary, vodárny, vozovny
  | 'kandelabr'   // pouliční kandelábrové a konzolové hodiny
  | 'zdymadlo'    // vltavská kanalizace
  | 'instituce'   // spořitelny, nemocnice, kasárna, úřady, ústavy
  | 'zastoupeni'  // prodej přes obchodní zastoupení
  | 'ostatni';

export interface HainzZaznam {
  /** Původní zápis z letáku (1904, německy). */
  original: string;
  /** Dnešní název lokality. */
  misto: string;
  /** ISO kód země (dnešní hranice). */
  zeme: string;
  okres?: string;
  /** Český popis objektu. */
  objekt: string;
  kategorie: HainzKategorie;
  /** Počet kusů (Stück) — většinou 1. */
  pocet: number;
  lat: number;
  lon: number;
  presnost: 'budova' | 'obec';
  /** Položka ze sekce „Elektrische Uhrenanlagen". */
  elektro?: boolean;
  /** Identifikace lokality nejistá. */
  nejiste?: boolean;
  pozn?: string;
}

/** Položky, které se nepodařilo lokalizovat (viz stránka mapy). */
